  --rust: #c9683c;
  --rust-hot: #e58a53;
  --moss: #7e8c60;
  --gold: #d6a756;
  --wood-dark: #3a2415;
  --wood-mid: #6b4325;
  --wood-light: #9b6738;
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-top: env(safe-area-inset-top, 0px);
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; overflow: hidden; background: #050605; }
body {
  font-family: 'Manrope', system-ui, sans-serif;
