@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 8px); } }

.tutorial {
  position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%);
  width: min(420px, 86vw); padding: 22px 24px; display: flex; gap: 18px; align-items: flex-start;
  background: linear-gradient(150deg, rgba(13,16,12,.94), rgba(8,10,8,.88));
