  concreteDark: new THREE.MeshStandardMaterial({ map: concreteTexture({ seed: 43, tint: [88, 88, 80] }), roughness: 0.95 }),
  asphalt: new THREE.MeshStandardMaterial({ map: asphaltTexture({ seed: 21 }), roughness: 0.96 }),
