298:     this.updateMarkers(dt);
299:     this.updateCamera(dt);
300:     this.updateCaption(dt);
301:     audio.update(dt);
302: 
303:     // hide tutorial after time
304:     if (this.tutorialShown && this.tutorialTimer > 0) {
305:       this.tutorialTimer -= dt;
306:       if (this.tutorialTimer <= 0) this.dismissTutorial();
307:     }
308:     // close pointer lock when not active
309:     if (this.state !== 'active' && document.pointerLockElement) document.exitPointerLock?.();
310:   }
311: 
312:   updateTasks(dt) {
313:     if (!this.tasks.length) return;
314:     const remaining = [];
315:     for (const task of this.tasks) {
316:       task.t += dt;
317:       let u = Math.min(1, task.t / task.duration);
318:       const e = task.ease === false ? u : u * u * (3 - 2 * u);
319:       try { task.fn?.(e, dt); } catch (err) { console.warn(err); }
320:       if (u >= 1) task.resolve?.(); else remaining.push(task);
321:     }
322:     this.tasks = remaining;
323:   }
324: 
325:   wait(duration) { return new Promise(resolve => this.tasks.push({ t: 0, duration, fn: null, resolve })); }
326:   tween(duration, fn, ease = true) { return new Promise(resolve => this.tasks.push({ t: 0, duration, fn, resolve, ease })); }
327: 
328:   updatePlayer(dt) {
329:     // input
330:     let ix = 0, iz = 0;
331:     if (this.keys['w'] || this.keys['arrowup']) iz -= 1;
332:     if (this.keys['s'] || this.keys['arrowdown']) iz += 1;
333:     if (this.keys['a']) ix -= 1;
334:     if (this.keys['d']) ix += 1;
335:     ix += this.touchMove.x;
336:     iz += this.touchMove.y;
337:     const len = Math.hypot(ix, iz);
338:     if (len > 1) { ix /= len; iz /= len; }
339:     const moving = len > 0.12;
340:     const running = !!this.keys['shift'];
341:     const targetCrouch = this.crouch ? 1 : 0;
342:     this.crouchAmt = damp(this.crouchAmt, targetCrouch, 9, dt);
343:     this.tim.setCrouch(this.crouchAmt);
344:     this.tim.setGun(false);
345: 
346:     if (moving) {
347:       // camera-relative movement
348:       const fwdX = -Math.sin(this.yaw), fwdZ = -Math.cos(this.yaw);
349:       const rightX = Math.cos(this.yaw), rightZ = -Math.sin(this.yaw);
350:       let vx = fwdX * -iz + rightX * ix;
351:       let vz = fwdZ * -iz + rightZ * ix;
352:       const vlen = Math.hypot(vx, vz) || 1;
353:       vx /= vlen; vz /= vlen;
354:       const speed = this.crouch ? 1.45 : (running ? 4.5 : 2.85);
355:       this.move.set(vx, vz);
356:       this.tryMove(vx * speed * dt, vz * speed * dt);
357:       const targetRot = Math.atan2(vx, vz);
358:       this.player.rotation.y = lerpAngle(this.player.rotation.y, targetRot, 1 - Math.exp(-12 * dt));
359:       this.stepTimer -= dt;
360:       if (this.stepTimer <= 0) {
361:         this.stepTimer = this.crouch ? 0.62 : (running ? 0.3 : 0.44);
362:         audio.step(running);
363:       }
364:       this.tim.setLocomotion(speed, dt);
365:     } else {
366:       this.tim.setLocomotion(0, dt);
367:     }
368:     this.tim.update(dt);
369: 
370:     // fence crossing rules
371:     const z = this.player.position.z;
372:     this.inside = z < 12;
373:     this.checkTriggers();
374:     this.updateHudState();
375:   }
376: 
377:   tryMove(dx, dz) {
378:     const p = this.player.position;
379:     const r = 0.32;
380:     const prevZ = p.z;
381:     // X
382:     let nx = p.x + dx;
383:     if (!this.collides(nx, p.z, r)) p.x = nx;
384:     // Z with fence crossing
385:     let nz = p.z + dz;
386:     const fenceCross = (prevZ - 12) * (nz - 12) <= 0 && Math.abs(nz - 12) < 0.9;
387:     if (fenceCross) {
388:       const atHole = Math.abs(p.x - this.compound.holeX) < this.compound.holeHalf;
389:       if (!(atHole && this.crouchAmt > 0.5)) {
390:         nz = prevZ > 12 ? 12.35 : 11.65;
391:       } else {
392:         this.inside = prevZ > 12;
393:         if (this.inside) this.onEnteredLot();
394:       }
395:     }
396:     if (!this.collides(p.x, nz, r)) p.z = nz;
397:     // world bounds
398:     const b = this.compound.bounds;
399:     p.x = clamp(p.x, b.minX + r, b.maxX - r);
400:     p.z = clamp(p.z, b.minZ + r, b.maxZ - r);
401:   }
402: 
403:   collides(x, z, r) {
404:     // building
405:     if (x > -22.5 - r && x < 22.5 + r && z < -16.9 + r && z > -42) return true;
406:     for (const c of this.compound.colliders) {
407:       if (c.name === 'store') continue;
408:       if (x > c.minX - r && x < c.maxX + r && z > c.minZ - r && z < c.maxZ + r) return true;
409:     }
410:     // gate posts
411:     if (Math.abs(z - 12) < 0.45 && (Math.abs(x - 5.1) < 0.3 || Math.abs(x + 5.1) < 0.3)) return true;
412:     // extra circles for cars/carts
413:     for (const c of this.circles || []) {
414:       if (Math.hypot(x - c.x, z - c.z) < c.r + r) return true;
415:     }
416:     return false;
417:   }
