599:   updateShards(dt) {
600:     if (!this.shards.length) return;
601:     for (let i = this.shards.length - 1; i >= 0; i--) {
602:       const s = this.shards[i];
603:       s.life -= dt;
604:       s.vy -= 9.8 * dt;
605:       s.mesh.position.x += s.vx * dt; s.mesh.position.y += s.vy * dt; s.mesh.position.z += s.vz * dt;
606:       s.mesh.rotation.x += s.rx * dt; s.mesh.rotation.z += s.rx * 0.7 * dt;
607:       if (s.mesh.position.y < 0.05) { s.mesh.position.y = 0.05; s.vy *= -0.2; s.vx *= 0.6; s.vz *= 0.5; }
608:       if (s.life <= 0) { s.mesh.visible = false; this.shards.splice(i, 1); }
609:     }
610:   }
