704:   /* ------------------------------ helpers ------------------------------ */
705:   interact() {
706:     if (this.branch === 'side' && this.state === 'active') {
707:       const p = this.player.position;
708:       if (Math.hypot(p.x - this.compound.ventTrigger.x, p.z - this.compound.ventTrigger.z) < 3.6) {
709:         this.startVentSequence();
710:       }
711:     }
712:   }
713: 
714:   updateCamera(dt) {
715:     if (this.state === 'choice') {
716:       const pos = new THREE.Vector3(3.4, 1.9, -11.7);
717:       const look = new THREE.Vector3(0, 1.6, -16.5);
718:       this.camera.position.lerp(pos, 1 - Math.exp(-3.5 * dt));
719:       this.cameraLook.lerp(look, 1 - Math.exp(-4 * dt));
720:       this.camera.lookAt(this.cameraLook);
721:       return;
722:     }
723:     if (this.state === 'sequence') {
724:       // sequences drive the camera directly; shake only
725:       if (this.cameraShake > 0) {
726:         this.camera.position.x += (Math.random() - 0.5) * this.cameraShake;
727:         this.camera.position.y += (Math.random() - 0.5) * this.cameraShake;
728:         this.cameraShake = Math.max(0, this.cameraShake - dt * 0.35);
729:       }
730:       return;
731:     }
732:     const p = this.player.position;
733:     const targetY = 1.52 - this.crouchAmt * 0.42;
734:     const pitch = this.pitch;
735:     const dist = 4.25 - this.crouchAmt * 0.35;
736:     const hd = Math.cos(pitch) * dist;
737:     const desired = new THREE.Vector3(
738:       p.x + Math.sin(this.yaw) * hd,
739:       p.y + targetY + 0.65 + Math.sin(pitch) * 3.0,
740:       p.z + Math.cos(this.yaw) * hd
741:     );
742:     // keep camera out of the store
743:     if (desired.x > -22.5 && desired.x < 22.5 && desired.z < -16.4) {
744:       desired.z = -16.2;
745:       desired.y = Math.max(desired.y, 2.2);
746:     }
747:     // keep camera above ground and inside bounds
748:     const b = this.compound.bounds;
749:     desired.x = clamp(desired.x, b.minX - 3, b.maxX + 3);
750:     desired.z = clamp(desired.z, b.minZ, b.maxZ + 4);
751:     desired.y = Math.max(0.65, desired.y);
752:     const k = 1 - Math.exp(-8 * dt);
