  const lamp = createStreetLamp({ height: 7, light: true, color: 0xffb36a, intensity: 30 });
  lamp.position.set(-5.6, 0, -16);
  lamp.rotation.y = Math.PI;
  scene.add(lamp);

  // moon
  const moon = createMoon(24, 0xd9ddc2, 0.75);
  moon.position.set(17, 9.5, -74);
