/* ---------- screens ---------- */
.screen {
  position: absolute; inset: 0; z-index: 10; pointer-events: none;
  opacity: 0; visibility: hidden; transition: opacity .7s ease, visibility .7s;
}
.screen.visible { opacity: 1; visibility: visible; pointer-events: auto; }
.screen > * { pointer-events: auto; }

/* ---------- loading ---------- */
#loading { background: #060806; z-index: 60; display: flex; align-items: center; justify-content: center; }
#loading.visible { display: flex; }
.load-inner { text-align: center; width: min(520px, 80vw); }
.load-mark {
  font-family: 'Bebas Neue'; font-size: 30px; letter-spacing: .2em; color: var(--rust);
  border: 1px solid rgba(201,104,60,.5); width: 64px; height: 48px; line-height: 46px;
  margin: 0 auto 18px; transform: rotate(-2deg);
}
.load-title { font-family: 'Bebas Neue'; font-size: clamp(42px, 7vw, 74px); letter-spacing: .08em; line-height: 1; }
.load-line { height: 2px; background: rgba(236,230,214,.12); margin: 26px 0 12px; overflow: hidden; }
.load-line i { display: block; height: 100%; width: 30%; background: var(--rust); animation: loadSweep 1.4s ease-in-out infinite; }
@keyframes loadSweep { 0% { transform: translateX(-110%); } 100% { transform: translateX(430%); } }
.load-sub { font-size: 9px; letter-spacing: .36em; color: var(--bone-dim); }

/* ---------- main menu ---------- */
#menu { background: linear-gradient(90deg, rgba(4,7,5,.78) 0%, rgba(4,7,5,.34) 42%, rgba(4,7,5,0) 66%, rgba(4,7,5,.3) 100%); }
.menu-top {
  position: absolute; top: 0; left: 0; right: 0; display: flex; justify-content: space-between; align-items: center;
  padding: calc(24px + var(--safe-top)) clamp(22px, 4vw, 60px) 0;
  position: absolute; left: 0; right: 0; bottom: calc(18px + var(--safe-bottom)); display: flex; justify-content: space-between;
  padding: 0 clamp(22px, 4vw, 60px); font-size: 7.5px; letter-spacing: .24em; color: rgba(236,230,214,.36);
}
.footer-center { opacity: .7; }

/* ---------- cutscene ---------- */
#cutsceneUI { position: absolute; inset: 0; z-index: 14; pointer-events: none; }
.scene-card {
  position: absolute; left: clamp(28px, 6vw, 92px); top: clamp(74px, 13vh, 140px);
  display: flex; flex-direction: column; gap: 7px; opacity: 0; transform: translateY(14px);
  transition: opacity .8s, transform .8s; text-shadow: 0 2px 12px #000;
}
.scene-card.show { opacity: 1; transform: none; }
.scene-card span { font-size: 9px; letter-spacing: .36em; color: var(--rust-hot); }
.scene-card strong { font-family: 'Bebas Neue'; font-size: clamp(30px, 3.6vw, 52px); letter-spacing: .06em; line-height: 1; }
#subtitleWrap {
  position: absolute; left: 50%; bottom: clamp(58px, 9.4vh, 110px); transform: translateX(-50%);
  width: min(780px, 84vw); text-align: center; opacity: 0; transition: opacity .35s;
}
#subtitleWrap.show { opacity: 1; }
#subtitleWrap p {
  margin: 6px auto 0; font-family: 'Special Elite'; font-size: clamp(16px, 1.75vw, 21px); line-height: 1.55;
  color: #f0e8d5; text-shadow: 0 2px 10px rgba(0,0,0,.95), 0 0 24px rgba(0,0,0,.8);
  max-width: 760px;
}
#speakerTag { font-size: 8px; letter-spacing: .34em; color: var(--rust-hot); text-shadow: 0 2px 8px #000; }
.skip-btn {
  position: absolute; right: clamp(22px, 4vw, 56px); top: clamp(22px, 4vw, 42px);
  font-size: 8px; letter-spacing: .26em; color: rgba(236,230,214,.66); padding: 10px 14px;
  border: 1px solid rgba(236,230,214,.22); background: rgba(5,7,5,.34); pointer-events: auto;
  transition: .25s; backdrop-filter: blur(6px);
}
.skip-btn:hover { color: #fff; border-color: rgba(236,230,214,.6); background: rgba(5,7,5,.6); }
.skip-btn span { color: var(--rust); margin-left: 4px; }
#cutProgress { position: absolute; left: clamp(22px, 4vw, 56px); bottom: clamp(20px, 4vh, 40px); width: 130px; height: 2px; background: rgba(236,230,214,.14); }
#cutProgress i { display: block; height: 100%; width: 0%; background: var(--rust); transition: width .2s linear; }

/* ---------- HUD ---------- */
#hud { position: absolute; inset: 0; z-index: 9; pointer-events: none; }
.hud-top {
  position: absolute; top: calc(26px + var(--safe-top)); left: clamp(18px, 3.6vw, 54px); right: clamp(18px, 3.6vw, 54px);
.chapter-card small { font-size: 8px; letter-spacing: .3em; color: rgba(236,230,214,.5); margin-top: 5px; }

/* story info */
#storyInfo {
  position: absolute; inset: 0; z-index: 44; display: flex; align-items: center; justify-content: center;
  opacity: 0; transition: opacity .8s; pointer-events: none;
}
#storyInfo.visible { opacity: 1; pointer-events: auto; }
.story-shade {
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at 50% 45%, rgba(38,28,18,.9), rgba(3,5,3,.97) 68%);
}
.story-card { position: relative; width: min(760px, 88vw); text-align: center; padding: 30px 20px; }
.story-kicker { font-size: 9px; letter-spacing: .44em; color: var(--rust-hot); }
.story-card h2 {
  font-family: 'Bebas Neue'; font-weight: 400; font-size: clamp(38px, 5.6vw, 74px); line-height: .94; letter-spacing: .035em;
  margin: 14px 0 18px;
}
.story-card h2 em { font-style: normal; color: transparent; background: linear-gradient(180deg, #e69a65, #a84e2e); -webkit-background-clip: text; background-clip: text; }
.story-card p { max-width: 520px; margin: 0 auto 28px; font-family: 'Special Elite'; font-size: clamp(13px, 1.4vw, 16px); line-height: 1.65; color: var(--bone-dim); }
.story-line { width: 220px; height: 1px; background: rgba(236,230,214,.14); margin: 26px auto 0; overflow: hidden; }
.story-line i { display: block; height: 100%; width: 100%; background: var(--rust); transform-origin: left; animation: storyLine 9s linear forwards; }
@keyframes storyLine { to { transform: scaleX(0); } }

/* mobile */
.mobile-ui { position: absolute; inset: 0; pointer-events: none; }
.joystick {
  position: absolute; left: 28px; bottom: calc(34px + var(--safe-bottom)); width: 116px; height: 116px;
  border: 1px solid rgba(236,230,214,.18); border-radius: 50%; background: rgba(10,13,9,.24);
  pointer-events: auto; touch-action: none; backdrop-filter: blur(3px);
}
.joystick::after { content: 'MOVE'; position: absolute; left: 50%; bottom: -18px; transform: translateX(-50%); font-size: 7px; letter-spacing: .28em; color: rgba(236,230,214,.35); }
.joystick .stick {
  position: absolute; left: 50%; top: 50%; width: 48px; height: 48px; margin: -24px 0 0 -24px; border-radius: 50%;
  background: radial-gradient(circle at 40% 35%, rgba(236,230,214,.28), rgba(236,230,214,.12));
  border: 1px solid rgba(236,230,214,.3); box-shadow: 0 6px 16px rgba(0,0,0,.4);
}
.mobile-buttons { position: absolute; right: 26px; bottom: calc(38px + var(--safe-bottom)); display: flex; gap: 14px; align-items: flex-end; pointer-events: auto; }
.round-btn {
  width: 76px; height: 76px; border-radius: 50%; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
  border: 1px solid rgba(236,230,214,.28); background: rgba(9,12,9,.46); backdrop-filter: blur(7px); touch-action: none;
  box-shadow: 0 6px 20px rgba(0,0,0,.35);
}
.round-btn span { font-family: 'Bebas Neue'; font-size: 23px; color: var(--bone); line-height: 1; }
.round-btn small { font-size: 6px; letter-spacing: .22em; color: var(--bone-dim); }
.round-btn.active { background: rgba(201,104,60,.36); border-color: var(--rust); }
.crouch-btn { border-color: rgba(201,104,60,.52); box-shadow: 0 0 0 0 rgba(201,104,60,.4); }
.crouch-btn.pulse { animation: btnPulse 1.3s ease-out infinite; }
@keyframes btnPulse { 0% { box-shadow: 0 0 0 0 rgba(201,104,60,.45); } 70% { box-shadow: 0 0 0 18px rgba(201,104,60,0); } 100% { box-shadow: 0 0 0 0 rgba(201,104,60,0); } }

/* ---------- choices ---------- */
#choiceUI { position: absolute; inset: 0; z-index: 20; pointer-events: none; }
#choiceUI.hidden + .hidden { }
.choice-shade {
  position: absolute; inset: 0; background:
    radial-gradient(ellipse at 50% 60%, transparent 0 18%, rgba(3,5,3,.55) 68%, rgba(3,4,3,.82) 100%),
    linear-gradient(0deg, rgba(4,6,4,.9), transparent 62%);
  opacity: 0; transition: opacity .6s;
}
#choiceUI.on .choice-shade { opacity: 1; }
.choice-wrap {
  position: absolute; left: 50%; bottom: clamp(44px, 9vh, 100px); transform: translate(-50%, 30px);
  width: min(760px, 90vw); opacity: 0; transition: opacity .5s, transform .6s cubic-bezier(.2,.8,.2,1);
  pointer-events: auto;
}
#choiceUI.on .choice-wrap { opacity: 1; transform: translate(-50%, 0); }
.choice-head { text-align: center; margin-bottom: 18px; text-shadow: 0 2px 10px #000; }
.choice-kicker { font-size: 8px; letter-spacing: .4em; color: var(--rust-hot); }
.choice-head h2 { font-family: 'Bebas Neue'; font-size: clamp(34px, 4vw, 52px); font-weight: 400; letter-spacing: .05em; margin: 3px 0 3px; line-height: 1; }
.choice-head p { margin: 0; font-family: 'Special Elite'; font-size: 13px; color: var(--bone-dim); }
.choice-list { display: flex; flex-direction: column; gap: 8px; }
.choice-option {
  position: relative; display: flex; align-items: center; gap: 16px; text-align: left;
  padding: 13px 18px 13px 16px; background: linear-gradient(90deg, rgba(12,15,11,.92), rgba(12,15,11,.7));
  border: 1px solid rgba(236,230,214,.15); border-left: 2px solid rgba(236,230,214,.16);
  transition: border-color .22s, background .22s, transform .22s; overflow: hidden;
}
.choice-option::after {
  content: ''; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(201,104,60,.14), transparent 55%);
  opacity: 0; transition: opacity .22s;
}
.choice-option:hover, .choice-option.focus {
  border-color: rgba(201,104,60,.8); border-left-color: var(--rust); transform: translateX(4px);
  background: linear-gradient(90deg, rgba(25,22,16,.96), rgba(12,15,11,.82));
}
.choice-option:hover::after, .choice-option.focus::after { opacity: 1; }
.choice-num {
  position: relative; z-index: 1; font-family: 'Bebas Neue'; font-size: 15px; color: var(--rust-hot);
  width: 26px; height: 26px; border: 1px solid rgba(201,104,60,.5); display: flex; align-items: center; justify-content: center;
  flex: 0 0 auto;
}
.choice-copy { position: relative; z-index: 1; flex: 1; min-width: 0; }
.choice-copy strong { display: block; font-family: 'Bebas Neue'; font-size: 22px; font-weight: 400; letter-spacing: .08em; line-height: 1; }
.choice-copy small { display: block; font-size: 9.5px; color: var(--bone-dim); margin-top: 4px; letter-spacing: .02em; }
.choice-arrow { position: relative; z-index: 1; color: rgba(236,230,214,.34); font-size: 18px; transition: .22s; }
.choice-option:hover .choice-arrow, .choice-option.focus .choice-arrow { color: var(--rust-hot); transform: translateX(3px); }
.choice-timer { display: flex; align-items: center; gap: 12px; margin-top: 14px; width: 280px; margin-left: auto; margin-right: auto; }
.choice-timer span { font-size: 7px; letter-spacing: .3em; color: rgba(236,230,214,.46); white-space: nowrap; }
.choice-timer-track { flex: 1; height: 2px; background: rgba(236,230,214,.14); overflow: hidden; }
.choice-timer-track i { display: block; height: 100%; width: 100%; background: var(--rust); transform-origin: left; transition: transform .2s linear; }
.choice-timer.danger span { color: var(--rust-hot); animation: hintPulse .8s infinite; }

/* ---------- end screen ---------- */
#endScreen {
  background:
    radial-gradient(ellipse at 50% 42%, rgba(54,30,17,.36), transparent 52%),
    linear-gradient(180deg, rgba(4,6,4,.96), #040504);
  z-index: 40; display: flex; align-items: center; justify-content: center; text-align: center;
}
.end-glow { position: absolute; width: 700px; height: 700px; border-radius: 50%; background: radial-gradient(circle, rgba(201,104,60,.11), transparent 65%); pointer-events: none; }
.end-inner { position: relative; width: min(780px, 88vw); padding: 20px 0; }
.end-kicker { font-size: 9px; letter-spacing: .44em; color: var(--rust-hot); }
#endTitle { font-family: 'Bebas Neue'; font-weight: 400; font-size: clamp(48px, 6.4vw, 88px); letter-spacing: .04em; line-height: .95; margin: 12px 0 12px; }
#endCopy { font-family: 'Special Elite'; color: var(--bone-dim); font-size: clamp(13px, 1.5vw, 17px); line-height: 1.6; max-width: 560px; margin: 0 auto; }
.remembered {
  display: inline-block; margin: 24px auto 0; padding: 8px 16px; font-size: 8px; letter-spacing: .28em;
