await page.waitForTimeout(11000);
await page.screenshot({ path: `${OUT}/08-standoff.png` });
console.log('state', await page.evaluate(() => window.__lastCan.game.state), 'choiceKind', await page.evaluate(() => window.__lastCan.game.choiceKind));

// choose threaten
await page.evaluate(() => window.__lastCan.game.choose(0));
await page.waitForTimeout(6000);
await page.screenshot({ path: `${OUT}/09-escape.png` });
console.log('escape', await page.evaluate(() => JSON.stringify(window.__lastCan.game.escape)));

// QTE tap many times
await page.waitForTimeout(3000);
await page.screenshot({ path: `${OUT}/10-qte.png` });
const qteMode = await page.evaluate(() => window.__lastCan.game.qte?.mode);
console.log('qteMode', qteMode);
if (qteMode === 'tap') {
  for (let i = 0; i < 16; i++) { await page.evaluate(() => window.__lastCan.game.qteInput('tap')); await page.waitForTimeout(60); }
}
await page.waitForTimeout(8000);
await page.screenshot({ path: `${OUT}/11-chase.png` });
console.log('phase', await page.evaluate(() => window.__lastCan.game.phase), 'qte', await page.evaluate(() => window.__lastCan.game.qte?.mode));

// chase QTE
const m2 = await page.evaluate(() => window.__lastCan.game.qte?.mode);
if (m2) { await page.evaluate(() => window.__lastCan.game.qteInput('swipe')); }
await page.waitForTimeout(9000);
await page.screenshot({ path: `${OUT}/12-gate.png` });
console.log('state', await page.evaluate(() => window.__lastCan.game.state), 'choiceKind', await page.evaluate(() => window.__lastCan.game.choiceKind));

if (await page.evaluate(() => window.__lastCan.game.choiceKind === 'gate')) {
  await page.evaluate(() => window.__lastCan.game.choose(0));
}
await page.waitForTimeout(9000);
await page.screenshot({ path: `${OUT}/13-truck.png` });
console.log('phase', await page.evaluate(() => window.__lastCan.game.phase), 'qte', await page.evaluate(() => window.__lastCan.game.qte?.mode));

// do truck QTEs
for (let k = 0; k < 4; k++) {
