export class CutsceneDirector {
  constructor({ onFade, onSubtitle, onCard, onProgress, onScene, onComplete, onLetterbox, onSkipUI }) {
    this.onFade = onFade;
    this.onSubtitle = onSubtitle;
    this.onCard = onCard;
    this.onProgress = onProgress;
    this.onScene = onScene;
    this.onComplete = onComplete;
    this.onLetterbox = onLetterbox;
    this.onSkipUI = onSkipUI;
    this.scene = null;
    this.camera = null;
    this.current = null;
    this.elapsed = 0;
    this.running = false;
    this.paused = false;
    this.aborted = false;
    this.resolveScene = null;
    this.activeSub = null;
    this.phase = 'idle';
    this.fadeTimer = 0;
    this.onlyScene = null;
    this.scenes = makeScenes();
  }

  async play({ from = 0, only = null, skipCard = false } = {}) {
    this.running = true;
    this.aborted = false;
    this.paused = false;
    this.onlyScene = only;
    this.onLetterbox?.(true);
    this.onSkipUI?.(true);
    this.onFade?.(1);
    await new Promise(r => setTimeout(r, 80));
    this.onFade?.(0);
