import { createRequire } from 'node:module';
import { join } from 'node:path';
import { mkdirSync } from 'node:fs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const OUT = '/tmp/opencode/shots';
mkdirSync(OUT, { recursive: true });

const browser = await chromium.launch({ args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message + '\n' + (e.stack || '')));

const waitFor = async (fn, timeout = 20000, label = '') => {
  const start = Date.now();
  while (Date.now() - start < timeout) {
    const v = await page.evaluate(fn).catch(() => null);
    if (v) return v;
    await page.waitForTimeout(150);
  }
  console.log('TIMEOUT waiting', label);
  return null;
};
const shot = async (n) => { await page.screenshot({ path: `${OUT}/${n}.png` }); console.log('shot', n); };

await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(2000);
await shot('01-menu');

await page.click('#playBtn');
await page.waitForTimeout(2600);
await shot('02-cutscene');
console.log('cutscene mode', await page.evaluate(() => window.__lastCan?.mode));

// skip intro
await page.evaluate(() => window.__lastCan.director.skip());
const gameReady = await waitFor(() => window.__lastCan.mode === 'game' && window.__lastCan.game?.phase === 'lot', 15000, 'game start');
console.log('game ready', !!gameReady);
await page.waitForTimeout(1200);
await shot('03-lot');

// store
await page.evaluate(() => window.__lastCan.game.enterStore('shoot'));
await waitFor(() => window.__lastCan.game.state === 'active' && window.__lastCan.game.phase === 'store', 12000, 'store');
await page.waitForTimeout(800);
await shot('04-store');

// collect all cans
const canNames = await page.evaluate(async () => {
  const g = window.__lastCan.game;
  const out = [];
  for (const can of g.interior.cans) {
    g.player.position.set(can.position.x, 0, can.position.z + 0.35);
    await new Promise(r => setTimeout(r, 160));
    g.interact();
    out.push(can.userData.name);
  }
  return out;
});
console.log('cans', canNames.length, 'found', await page.evaluate(() => window.__lastCan.game.cansFound));
await shot('05-cans');

// note
await page.evaluate(() => {
  const g = window.__lastCan.game;
  const n = g.interior.interactables.note;
  g.player.position.set(n.x + 0.2, 0, n.z + 0.3);
});
await page.waitForTimeout(400);
await page.evaluate(() => window.__lastCan.game.interact());
await page.waitForTimeout(700);
await shot('06-note');
console.log('noteOpen', await page.evaluate(() => window.__lastCan.game.noteOpen));
await page.evaluate(() => window.__lastCan.game.closeNote());
await page.waitForTimeout(300);

// blood wall
await page.evaluate(() => {
  const g = window.__lastCan.game;
  const b = g.interior.interactables.blood;
  g.player.position.set(b.x + 0.3, 0, b.z + 0.6);
});
await page.waitForTimeout(500);
await page.evaluate(() => window.__lastCan.game.interact());
await page.waitForTimeout(700);
await shot('07-blood');

// keypad
await page.evaluate(() => {
  const g = window.__lastCan.game;
  const k = g.interior.interactables.keypad;
  g.player.position.set(k.x - 0.8, 0, k.z + 0.7);
});
await page.waitForTimeout(500);
await page.evaluate(() => window.__lastCan.game.interact());
await page.waitForTimeout(700);
await shot('08-keypad');
for (const d of '261212') await page.evaluate((d) => window.__lastCan.game.pressKeypad(d), d);
await waitFor(() => window.__lastCan.game.keypadUnlocked, 5000, 'keypad unlock');
await page.waitForTimeout(900);
await shot('09-fuel-open');
console.log('keypadUnlocked', await page.evaluate(() => window.__lastCan.game.keypadUnlocked));

// fuel → standoff
await page.evaluate(() => {
  const g = window.__lastCan.game;
  const f = g.interior.interactables.fuel;
  g.player.position.set(f.x - 0.3, 0, f.z + 0.7);
});
await page.waitForTimeout(500);
await page.evaluate(() => window.__lastCan.game.interact());
const standoff = await waitFor(() => window.__lastCan.game.choiceKind === 'standoff' && window.__lastCan.game.state === 'choice', 25000, 'standoff choice');
console.log('standoff choice', !!standoff);
await shot('10-standoff');

// threaten
await page.evaluate(() => window.__lastCan.game.choose(0));
const escape = await waitFor(() => window.__lastCan.game.escape?.active, 12000, 'escape timer');
console.log('escape active', !!escape);
await page.waitForTimeout(1200);
await shot('11-escape');
const qte1 = await waitFor(() => window.__lastCan.game.qte?.mode === 'tap', 20000, 'jack QTE');
console.log('jack qte', !!qte1);
await shot('12-qte');
if (qte1) {
  for (let i = 0; i < 20; i++) {
    const still = await page.evaluate(() => !!window.__lastCan.game.qte);
    if (!still) break;
    await page.evaluate(() => window.__lastCan.game.qteInput('tap'));
    await page.waitForTimeout(70);
  }
}
const chase = await waitFor(() => window.__lastCan.game.phase === 'chase', 30000, 'chase');
console.log('chase', !!chase);
await page.waitForTimeout(1500);
await shot('13-chase');

const qte2 = await waitFor(() => window.__lastCan.game.qte?.mode === 'swipeRight', 25000, 'kick QTE');
console.log('kick qte', !!qte2);
if (qte2) await page.evaluate(() => window.__lastCan.game.qteInput('swipe'));
await shot('14-kick');

const gate = await waitFor(() => window.__lastCan.game.choiceKind === 'gate', 25000, 'gate choice');
console.log('gate choice', !!gate);
await shot('15-gate');
if (gate) await page.evaluate(() => window.__lastCan.game.choose(0));
await page.waitForTimeout(900);
await shot('16-jaake');

const truck = await waitFor(() => window.__lastCan.game.phase === 'truck', 25000, 'truck');
console.log('truck', !!truck);
await shot('17-truck');

// do all ignition QTEs (first fails, then succeed)
for (let k = 0; k < 6; k++) {
  const q = await waitFor(() => window.__lastCan.game.qte?.mode === 'swipeDown', 12000, 'ignition qte ' + k);
  if (!q) break;
  await page.evaluate(() => window.__lastCan.game.qteInput('swipe'));
  await page.waitForTimeout(1200);
  if (await page.evaluate(() => window.__lastCan.game.truck?.driving)) break;
}
console.log('driving', await page.evaluate(() => window.__lastCan.game.truck?.driving));
await page.waitForTimeout(1500);
await shot('18-driving');

const end = await waitFor(() => window.__lastCan.mode === 'end', 40000, 'end screen');
console.log('end', !!end);
await page.waitForTimeout(1200);
await shot('19-end');

console.log('--- ERRORS ---');
console.log(errors.length ? errors.join('\n') : 'none');
await browser.close();

