cd /home/runner/work/PlayGround/PlayGround && python3 - <<'EOF'
p='src/main.js'; s=open(p).read()
old = """  // fast-forward game logic (used by automated playthroughs)
  advance(seconds = 1) {
    if (!game) return;
    const steps = Math.min(1200, Math.max(1, Math.round(seconds * 60)));
    for (let i = 0; i < steps; i++) game.update(1 / 60);
    if (game.scene && game.camera) renderer.render(game.scene, game.camera);
  },"""
new = """  // fast-forward game logic (used by automated playthroughs)
  async advance(seconds = 1) {
    if (!game) return;
    const steps = Math.min(1800, Math.max(1, Math.round(seconds * 60)));
    for (let i = 0; i < steps; i++) {
      game.update(1 / 60);
      if (i % 8 === 7) await new Promise(r => setTimeout(r, 0));
    }
    if (game.scene && game.camera) renderer.render(game.scene, game.camera);
  },"""
assert old in s
s = s.replace(old, new)
open(p,'w').write(s)
EOF
node --check src/main.js && echo ok
